const body = $json.body ?? $json;
const driveFileId = body.driveFileId;
if (typeof driveFileId !== 'string' || !/^[A-Za-z0-9_-]{10,200}$/.test(driveFileId)) throw new Error('driveFileId must be a valid Google Drive file ID.');
const notebook = body.notebook === undefined ? '' : body.notebook;
if (typeof notebook !== 'string' || notebook.length > 500) throw new Error('notebook must be a string of at most 500 characters.');
return [{json:{driveFileId,notebook:notebook.trim(),file_source:`https://docs.google.com/document/d/${driveFileId}/edit`}}];

const response = $input.first()?.json;
const request = $('Validate exported document request').first()?.json;
if (!response || !request) throw new Error('Google Drive export response or request is unavailable.');
const code = Number(response.statusCode ?? 0);
if (code < 200 || code >= 300) throw new Error(`Google Drive export failed (HTTP ${code}): ${typeof response.body === 'string' ? response.body.slice(0, 500) : JSON.stringify(response.body)}`);
if (typeof response.body !== 'string' || !response.body.trim()) throw new Error('Google Drive returned an empty or non-text export. Ensure the file is a Google Doc exported from NotebookLM.');
if (response.body.length > 500000) throw new Error('Exported text exceeds the 500000-character limit.');
return [{json:{text:response.body,file_source:request.file_source,notebook:request.notebook}}];

const response = $input.first().json;
const code = Number(response.statusCode ?? 0);
const body = response.body ?? {};
const source = $('Validate exported document request').first().json.file_source;
const detail = typeof body.detail === 'string' ? body.detail : '';
if (code >= 200 && code < 300) {
  if (body.status !== 'success' || typeof body.track_id !== 'string' || !body.track_id) throw new Error(`LightRAG returned an incomplete success for ${source}: ${JSON.stringify(body)}`);
  return [{json:{status:'queued',message:'LightRAG accepted the document for background processing; ingestion is not complete yet.',file_source:source,queued:1,alreadyPresent:0,track_id:body.track_id}}];
}
if (code === 409 && detail.startsWith('Document storage already contains')) return [{json:{status:'already_present',message:'This source is already present in LightRAG.',file_source:source,queued:0,alreadyPresent:1}}];
throw new Error(`LightRAG rejected ${source} (HTTP ${code}): ${detail || JSON.stringify(body)}`);
